import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTimetable() {
  const [timetable, setTimetable] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [formData, setFormData] = useState({ day: 'Monday', time_slot: '', grade: 'Grade 6', subject_id: '', teacher_id: '' });
  
  // 🚨 Validation Errors මතක තබා ගන්නා අලුත් State එක
  const [errors, setErrors] = useState({});

  const fetchTimetable = () => axios.get('http://localhost:8082/api/timetable').then(res => setTimetable(res.data));
  const fetchSubjects = () => axios.get('http://localhost:8082/api/view-subjects').then(res => setSubjects(res.data));
  const fetchTeachers = () => axios.get('http://localhost:8082/api/view-teachers').then(res => setTeachers(res.data));

  useEffect(() => { fetchTimetable(); fetchSubjects(); fetchTeachers(); }, []);

  // 🟢 ටයිම් ටේබල් ෆෝම් එක පරික්ශා කරන වැලිඩේෂන් ෆන්ක්ෂන් එක
  const validateForm = () => {
    let formErrors = {};

    // 1. Time Slot එක හිස්දැයි බැලීම
    if (!formData.time_slot.trim()) {
      formErrors.time_slot = "Time slot description is required!";
    }

    // 2. විෂයක් තෝරාගෙන තිබේදැයි බැලීම
    if (!formData.subject_id) {
      formErrors.subject_id = "Please select a valid subject from the list!";
    }

    // 3. ගුරුවරයෙක් තෝරාගෙන තිබේදැයි බැලීම
    if (!formData.teacher_id) {
      formErrors.teacher_id = "Please assign an active teacher for this slot!";
    }

    setErrors(formErrors);
    return Object.keys(formErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    // වැලිඩේෂන් එක සාර්ථක නම් පමණක් API එකට ඩේටා යවයි
    if (!validateForm()) return;

    const apiPath = isEditing ? `http://localhost:8082/api/timetable/${editId}` : 'http://localhost:8082/api/timetable';
    const method = isEditing ? axios.put : axios.post;

    method(apiPath, formData).then((res) => {
      if (res.data.status === "Error") alert("Error: " + res.data.error);
      else { fetchTimetable(); resetForm(); }
    }).catch(() => alert("Server Error!"));
  };

  const handleEdit = (t) => {
    setIsEditing(true);
    setEditId(t.id);
    setErrors({}); // පරණ වැරදි මැකීම
    
    const matchedSubject = subjects.find(s => s.subject_name === t.subject);
    const matchedTeacher = teachers.find(tc => tc.name === t.teacher);

    setFormData({
      day: t.day,
      time_slot: t.time_slot,
      grade: t.grade,
      subject_id: matchedSubject ? matchedSubject.id : '',
      teacher_id: matchedTeacher ? matchedTeacher.id : ''
    });
    setShowForm(true);
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this slot?")) {
      axios.delete(`http://localhost:8082/api/timetable/${id}`).then(() => fetchTimetable());
    }
  };

  const resetForm = () => { 
    setShowForm(false); 
    setIsEditing(false);
    setEditId(null);
    setErrors({}); // එරර් ස්ටේට් එක හිස් කිරීම
    setFormData({ day: 'Monday', time_slot: '', grade: 'Grade 6', subject_id: '', teacher_id: '' }); 
  };

  const filteredTimetable = timetable.filter(t => 
    (t.subject || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
    (t.teacher || '').toLowerCase().includes(searchQuery.toLowerCase())
  );

  const gradeOrder = ['Grade 6', 'Grade 7', 'Grade 8', 'Grade 9', 'Grade 10', 'Grade 11', 'Grade 12'];

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      
      <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', marginBottom: '25px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ margin: 0, color: '#1e293b', fontSize: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>📅 Manage Class Timetable</h2>
          <div style={{ display: 'flex', gap: '15px' }}>
            <input type="text" placeholder="Search Subject or Teacher..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.searchInput} />
            <button onClick={() => setShowForm(true)} style={styles.primaryBtn}>+ Add New Class</button>
          </div>
        </div>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
        {gradeOrder.map((gradeName) => {
          const classesForGrade = filteredTimetable
            .filter(t => t.grade === gradeName)
            .sort((a, b) => b.id - a.id);

          if (classesForGrade.length === 0) return null;

          return (
            <div key={gradeName} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', borderLeft: '5px solid #0284c7' }}>
              
              <div style={{ display: 'inline-block', backgroundColor: '#e0f2fe', color: '#0369a1', padding: '6px 16px', borderRadius: '20px', fontWeight: 'bold', fontSize: '13px', marginBottom: '15px' }}>
                🎓 {gradeName} Schedule
              </div>

              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid #e2e8f0' }}>
                    <th style={styles.th}>No.</th>
                    <th style={styles.th}>Day</th>
                    <th style={styles.th}>Time Slot</th>
                    <th style={styles.th}>Subject</th>
                    <th style={styles.th}>Teacher</th>
                    <th style={{...styles.th, textAlign: 'center'}}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {classesForGrade.map((t, index) => (
                    <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                      <td style={styles.td}>{classesForGrade.length - index}</td>
                      <td style={{...styles.td, fontWeight: 'bold', color: '#1e293b'}}>{t.day}</td>
                      <td style={{...styles.td, color: '#475569', fontSize: '13px'}}>{t.time_slot}</td>
                      <td style={{...styles.td, fontWeight: 'bold', color: '#15803d'}}>{t.subject}</td>
                      <td style={{...styles.td, color: '#475569'}}>{t.teacher}</td>
                      <td style={{...styles.td, textAlign: 'center'}}>
                        <button onClick={() => handleEdit(t)} style={styles.iconBtn}>✏️</button>
                        <button onClick={() => handleDelete(t.id)} style={styles.iconBtn}>🗑️</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        })}
      </div>

      {showForm && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>{isEditing ? '✏️ Edit Class Slot' : '➕ Add New Class Slot'}</h3>
            
            {/* HTML5 Required tooltips වැළැක්වීමට noValidate යෙදුවා */}
            <form onSubmit={handleSubmit} noValidate style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              
              <div style={styles.inputWrapper}>
                <label style={styles.label}>Select Day</label>
                <select value={formData.day} onChange={e => setFormData({...formData, day: e.target.value})} style={styles.input}>
                  <option value="Monday">Monday</option>
                  <option value="Tuesday">Tuesday</option>
                  <option value="Wednesday">Wednesday</option>
                  <option value="Thursday">Thursday</option>
                  <option value="Friday">Friday</option>
                  <option value="Saturday">Saturday</option>
                  <option value="Sunday">Sunday</option>
                </select>
              </div>

              <div style={styles.inputWrapper}>
                <label style={styles.label}>Time Slot (e.g. 8.00 AM - 10.00 AM)</label>
                <input type="text" placeholder="Enter Time Slot" value={formData.time_slot} onChange={e => setFormData({...formData, time_slot: e.target.value})} style={{...styles.input, border: errors.time_slot ? '1px solid #dc2626' : '1px solid #cbd5e1'}} />
                {errors.time_slot && <span style={styles.errorText}>⚠️ {errors.time_slot}</span>}
              </div>

              <div style={styles.inputWrapper}>
                <label style={styles.label}>Select Grade</label>
                <select value={formData.grade} onChange={e => setFormData({...formData, grade: e.target.value})} style={styles.input}>
                  <option value="Grade 6">Grade 6</option>
                  <option value="Grade 7">Grade 7</option>
                  <option value="Grade 8">Grade 8</option>
                  <option value="Grade 9">Grade 9</option>
                  <option value="Grade 10">Grade 10</option>
                  <option value="Grade 11">Grade 11</option>
                  <option value="Grade 12">Grade 12</option>
                </select>
              </div>

              <div style={styles.inputWrapper}>
                <label style={styles.label}>Select Subject</label>
                <select value={formData.subject_id} onChange={e => setFormData({...formData, subject_id: e.target.value})} style={{...styles.input, border: errors.subject_id ? '1px solid #dc2626' : '1px solid #cbd5e1'}}>
                  <option value="">-- Choose Subject --</option>
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.subject_name} ({s.subject_code})</option>)}
                </select>
                {errors.subject_id && <span style={styles.errorText}>⚠️ {errors.subject_id}</span>}
              </div>

              <div style={styles.inputWrapper}>
                <label style={styles.label}>Select Teacher</label>
                <select value={formData.teacher_id} onChange={e => setFormData({...formData, teacher_id: e.target.value})} style={{...styles.input, border: errors.teacher_id ? '1px solid #dc2626' : '1px solid #cbd5e1'}}>
                  <option value="">-- Choose Teacher --</option>
                  {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                </select>
                {errors.teacher_id && <span style={styles.errorText}>⚠️ {errors.teacher_id}</span>}
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '15px' }}>
                <button type="button" onClick={resetForm} style={styles.cancelBtn}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>{isEditing ? 'Update Slot' : 'Add to Timetable'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  searchInput: { padding: '8px 15px', borderRadius: '20px', border: '1px solid #cbd5e1', outline: 'none', width: '240px', fontSize: '13px', backgroundColor: '#f8fafc' },
  primaryBtn: { padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' },
  th: { padding: '12px 10px', color: '#64748b', fontWeight: 'bold', fontSize: '13px' },
  td: { padding: '15px 10px', fontSize: '14px', verticalAlign: 'middle' },
  iconBtn: { background: 'none', border: 'none', cursor: 'pointer', fontSize: '16px', marginRight: '10px' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  modal: { backgroundColor: 'white', padding: '25px 30px', borderRadius: '15px', width: '460px', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' },
  input: { padding: '10px 15px', borderRadius: '8px', width: '100%', boxSizing: 'border-box', outline: 'none', fontSize: '13px', backgroundColor: '#f8fafc', transition: 'all 0.2s' },
  label: { fontSize: '12px', color: '#64748b', fontWeight: 'bold', marginBottom: '2px', textAlign: 'left', display: 'block' },
  cancelBtn: { padding: '10px 20px', background: 'none', color: '#64748b', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  saveBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  inputWrapper: { display: 'flex', flexDirection: 'column', gap: '4px', width: '100%' },
  // 🔴 එරර් මැසේජ් ලස්සනට පෙන්වීමට ස්ටයිල් එක
  errorText: { color: '#dc2626', fontSize: '11px', fontWeight: '500', marginTop: '1px', display: 'block', textAlign: 'left' }
};
